1	package contractsentinel
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"os"
8		"path/filepath"
9		"reflect"
10		"strings"
11		"testing"
12	)
13	
14	// jsonEscapedR is the six-character JSON unicode escape that decodes to the
15	// letter r; it is built by concatenation so the source never carries the
16	// escape-looking literal as one piece.
17	const jsonEscapedR = `\` + `u0072`
18	
19	// 本文件锁定“归档读取”侧规则定义 requiresABI 成员的类型规则。audit 提交侧
20	// 早已拒绝 null 等非布尔值，但读取已保存报告时 json.Unmarshal 会把正式
21	// requiresABI 成员的 null 静默解码成 Go 零值 false：把一条原本“不需要 ABI”
22	// 的规则在归档里从 false 改成 null，重算的报告标识、规则状态与缺陷绑定仍
23	// 全部成立，读出的规则定义也显示 false，归档内容不合法的事实被完全掩盖。
24	//
25	// 修正后，正式成员（约定拼写，含 Unicode 转义写法）一旦出现就只允许 JSON
26	// 布尔值 true/false；null、字符串、数字、对象、数组都使整份归档判为损坏，
27	// 与规则是否已检查、是否发现缺陷无关，也不能只跳过该规则返回其余部分。
28	// 省略该成员仍表示 false；RequiresABI 或两侧带空格的名称只是扩展信息，其
29	// 中的 null 不触发本错误，也不能替代或挽救正式成员。
30	
31	// mutateRuleRequiresABI 把归档中指定规则的 requiresABI 成员做一次文本替换。
32	func mutateRuleRequiresABI(t *testing.T, doc, ruleID, newFragment string) string {
33		t.Helper()
34		old := `"id":"` + ruleID + `","kind":"`
35		idx := strings.Index(doc, old)
36		if idx < 0 {
37			t.Fatalf("test setup: rule %s not found in archive", ruleID)
38		}
39		rest := doc[idx:]
40		marker := `"requiresABI":`
41		at := strings.Index(rest, marker)
42		if at < 0 {
43			t.Fatalf("test setup: rule %s has no requiresABI member", ruleID)
44		}
45		valueStart := idx + at + len(marker)
46		// 找到该值之后的第一个逗号（规则对象内 requiresABI 后面总跟着 version）。
47		comma := strings.IndexByte(doc[valueStart:], ',')
48		if comma < 0 {
49			t.Fatalf("test setup: rule %s requiresABI value has no trailing comma", ruleID)
50		}
51		valueEnd := valueStart + comma
52		if newFragment == "" {
53			// 省略整个成员：连前导逗号一起删掉，避免留下空逗号。
54			return doc[:idx+at] + doc[valueEnd+1:]
55		}
56		return doc[:idx+at] + newFragment + doc[valueEnd:]
57	}
58	
59	// writeArchiveWithRuleRequiresABI marshals a legal report and replaces the
60	// requiresABI member of one rule with a raw fragment. When the fragment
61	// launders through the plain decoder (null decodes into the bool zero value),
62	// the reportId is recomputed so the archive is self-consistent and rejection
63	// can only come from the type gate. Other non-boolean JSON types never
64	// unmarshal into a Go bool, so the original id is kept: it may mismatch, but
65	// the type gate runs before the id comparison and rejects with the same
66	// corruption error.
67	func writeArchiveWithRuleRequiresABI(t *testing.T, dir string, r Report, ruleID, fragment string) string {
68		t.Helper()
69		r.ReportID = ReportID(r)
70		data, err := json.Marshal(r)
71		if err != nil {
72			t.Fatal(err)
73		}
74		doc := mutateRuleRequiresABI(t, string(data), ruleID, fragment)
75		if doc == string(data) {
76			t.Fatal("test setup: mutation did not change the archive")
77		}
78		id := r.ReportID
79		if strict, err := strictReportJSON([]byte(doc)); err == nil {
80			var decoded Report
81			if err := json.Unmarshal(strict, &decoded); err == nil {
82				newID := ReportID(decoded)
83				doc = strings.Replace(doc, `"reportId":"`+id+`"`, `"reportId":"`+newID+`"`, 1)
84				id = newID
85			}
86		}
87		if err := os.WriteFile(filepath.Join(dir, id+".json"), []byte(doc), 0o644); err != nil {
88			t.Fatal(err)
89		}
90		return id
91	}
92	
93	// expectCorruptRequiresABILoad asserts the full read-side contract for an
94	// illegal formal requiresABI value: errCorrupt naming the report id, the
95	// offending rule and the boolean requirement, a zero report and an untouched
96	// archive.
97	func expectCorruptRequiresABILoad(t *testing.T, dir, id, rule string) {
98		t.Helper()
99		path := filepath.Join(dir, id+".json")
100		before, err := os.ReadFile(path)
101		if err != nil {
102			t.Fatal(err)
103		}
104		got, err := LoadReport(dir, id)
105		if err == nil {
106			t.Fatalf("a non-boolean formal requiresABI must reject the whole archive, got %+v", got)
107		}
108		var ec errCorrupt
109		if !errors.As(err, &ec) {
110			t.Fatalf("illegal requiresABI classifies as errCorrupt, got %T: %v", err, err)
111		}
112		msg := err.Error()
113		if !strings.Contains(msg, id) {
114			t.Fatalf("error must name the report id %q: %v", id, err)
115		}
116		if !strings.Contains(msg, rule) {
117			t.Fatalf("error must name the offending rule %q: %v", rule, err)
118		}
119		if !strings.Contains(msg, "requiresABI must be a boolean") {
120			t.Fatalf("error must state requiresABI must be a boolean: %v", err)
121		}
122		if !reflect.DeepEqual(got, Report{}) {
123			t.Fatalf("failed read must return the zero report, got %+v", got)
124		}
125		after, err := os.ReadFile(path)
126		if err != nil {
127			t.Fatalf("corrupt archive must not be deleted: %v", err)
128		}
129		if string(after) != string(before) {
130			t.Fatal("failed read must not rewrite or repair the archive")
131		}
132	}
