1	package contractsentinel
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"os"
8		"path/filepath"
9		"reflect"
10		"strings"
11		"testing"
12	)
13	
14	// 本文件锁定“归档读取”侧规则文本成员的类型规则。ReportRule 的 id、kind、
15	// severity、invariant、version、status、note 都是 Go 字符串，json.Unmarshal
16	// 会把正式成员的 null 静默解码成零值 ""：给归档中一条没有说明的“通过”规则
17	// 加入 "note":null，读出的内容与省略该成员时逐字节相同，重算的报告标识、
18	// 规则状态与缺陷绑定全部吻合，归档没有按格式保存文本的事实被完全掩盖，
19	// diff 甚至可能把它判成“无变化”。
20	//
21	// 修正后，正式成员（约定拼写，含 Unicode 转义写法）一旦写出，其值就必须是
22	// JSON 字符串；null、布尔值、数字、对象、数组都使整份归档判为损坏，适用于
23	// 所有检查状态及没有 finding 的报告。错误点名报告标识、出错字段与规则数组
24	// 位置，规则有合法非空 id 时同时点名该规则。省略字段仍沿用默认值与必填校验，
25	// 显式空字符串仍按既有业务规则判断；大小写变体、带空格名称与未知扩展成员
26	// 继续被忽略，其中的 null 不触发本错误，也不能替代或挽救非法的正式成员。
27	
28	// jsonEscapedN is the six-character JSON unicode escape that decodes to the
29	// letter n; it is built by concatenation so the source never carries the
30	// escape-looking literal as one piece.
31	const jsonEscapedN = `\` + `u006e`
32	
33	// mutateRuleTextField 把归档中指定规则的某个文本成员替换为 raw 片段
34	// （如 null）；该成员不存在时把它插入到 id 成员之后。fragment 为空串表示
35	// 删除整个成员。
36	func mutateRuleTextField(t *testing.T, doc, ruleID, field, fragment string) string {
37		t.Helper()
38		idMember := `"id":"` + ruleID + `"`
39		idIdx := strings.Index(doc, idMember)
40		if idIdx < 0 {
41			t.Fatalf("test setup: rule %s not found in archive", ruleID)
42		}
43		ruleEnd := strings.IndexByte(doc[idIdx:], '}')
44		if ruleEnd < 0 {
45			t.Fatalf("test setup: rule %s object has no end", ruleID)
46		}
47		ruleEnd += idIdx
48		marker := `"` + field + `":`
49		at := strings.Index(doc[idIdx:ruleEnd], marker)
50		if at < 0 {
51			if fragment == "" {
52				t.Fatalf("test setup: rule %s has no %s member to remove", ruleID, field)
53			}
54			idEnd := idIdx + len(idMember)
55			return doc[:idEnd] + `,"` + field + `":` + fragment + doc[idEnd:]
56		}
57		at += idIdx
58		valueStart := at + len(marker)
59		var valueEnd int
60		if doc[valueStart] == '"' {
61			// 测试夹具中的字符串值不含转义引号，下一个引号即结束。
62			closing := strings.IndexByte(doc[valueStart+1:], '"')
63			if closing < 0 {
64				t.Fatalf("test setup: rule %s %s value has no closing quote", ruleID, field)
65			}
66			valueEnd = valueStart + 1 + closing + 1
67		} else {
68			end := strings.IndexAny(doc[valueStart:], ",}")
69			if end < 0 {
70				t.Fatalf("test setup: rule %s %s value has no end", ruleID, field)
71			}
72			valueEnd = valueStart + end
73		}
74		if fragment == "" {
75			// 删除整个成员：优先连同后随逗号，否则连同前导逗号。
76			if valueEnd < len(doc) && doc[valueEnd] == ',' {
77				return doc[:at] + doc[valueEnd+1:]
78			}
79			return doc[:at-1] + doc[valueEnd:]
80		}
81		return doc[:at] + `"` + field + `":` + fragment + doc[valueEnd:]
82	}
83	
84	// writeArchiveWithRuleText marshals a legal report, rewrites one rule text
85	// member with a raw fragment, recomputes the report id from the decoded
86	// content and writes the archive under that id. A null fragment launders
87	// through the plain decoder (null decodes into the string zero value), so the
88	// recomputed id keeps the archive self-consistent and rejection can only come
89	// from the type gate. Other non-string JSON types never unmarshal into a Go
90	// string, so the original id is kept: it may mismatch, but the type gate runs
91	// before the id comparison and rejects with the same corruption error.
92	func writeArchiveWithRuleText(t *testing.T, dir string, r Report, ruleID, field, fragment string) string {
93		t.Helper()
94		r.ReportID = ReportID(r)
95		data, err := json.Marshal(r)
96		if err != nil {
97			t.Fatal(err)
98		}
99		doc := mutateRuleTextField(t, string(data), ruleID, field, fragment)
100		if doc == string(data) {
101			t.Fatal("test setup: mutation did not change the archive")
102		}
103		id := r.ReportID
104		if strict, err := strictReportJSON([]byte(doc)); err == nil {
105			var decoded Report
106			if err := json.Unmarshal(strict, &decoded); err == nil {
107				newID := ReportID(decoded)
108				doc = strings.Replace(doc, `"reportId":"`+id+`"`, `"reportId":"`+newID+`"`, 1)
109				id = newID
110			}
111		}
112		if err := os.WriteFile(filepath.Join(dir, id+".json"), []byte(doc), 0o644); err != nil {
113			t.Fatal(err)
114		}
115		return id
116	}
117	
118	// expectCorruptRuleTextLoad asserts the full read-side contract for a
119	// non-string formal rule text member: errCorrupt naming the report id, the
120	// array position, the field and the string requirement (plus the rule id when
121	// the rule carries a legal one), a zero report and an untouched archive.
122	func expectCorruptRuleTextLoad(t *testing.T, dir, id, position, rule, field string) {
123		t.Helper()
124		path := filepath.Join(dir, id+".json")
125		before, err := os.ReadFile(path)
126		if err != nil {
127			t.Fatal(err)
128		}
129		got, err := LoadReport(dir, id)
130		if err == nil {
131			t.Fatalf("a non-string formal %s must reject the whole archive, got %+v", field, got)
132		}
133		var ec errCorrupt
134		if !errors.As(err, &ec) {
135			t.Fatalf("illegal %s classifies as errCorrupt, got %T: %v", field, err, err)
136		}
137		msg := err.Error()
138		if !strings.Contains(msg, id) {
139			t.Fatalf("error must name the report id %q: %v", id, err)
140		}
141		if !strings.Contains(msg, position) {
142			t.Fatalf("error must name the rule array position %q: %v", position, err)
143		}
144		if rule != "" && !strings.Contains(msg, rule) {
145			t.Fatalf("error must name the offending rule %q: %v", rule, err)
146		}
147		if !strings.Contains(msg, field+" must be a string") {
148			t.Fatalf("error must state %s must be a string: %v", field, err)
149		}
150		if !reflect.DeepEqual(got, Report{}) {
151			t.Fatalf("failed read must return the zero report, got %+v", got)
152		}
153		after, err := os.ReadFile(path)
154		if err != nil {
155			t.Fatalf("corrupt archive must not be deleted: %v", err)
156		}
157		if string(after) != string(before) {
158			t.Fatal("failed read must not rewrite or repair the archive")
159		}
160	}
161	
162	// --- 核心场景：给没有说明的“通过”规则加入 "note":null，标识仍一致也必须拒绝 ---
163	
164	func TestLoadReportNullNoteOnPassingRuleRejected(t *testing.T) {
165		dir := t.TempDir()
166		legal := oneDefectFixture()
167		id := writeArchiveWithRuleText(t, dir, legal, "r-pass", "note", `null`)
168	
169		// null 被洗成 ""：归档内 reportId、请求 id 与按解码内容重算的 id 三者
170		// 一致，且与合法报告的标识相同，除类型关外没有任何一关能拒绝它。
171		if want := ReportID(legal); id != want {
172			t.Fatalf("test setup: null note must launder to the legal report id %q, got %q", want, id)
173		}
174		data, err := os.ReadFile(filepath.Join(dir, id+".json"))
175		if err != nil {
176			t.Fatal(err)
177		}
178		if !bytes.Contains(data, []byte(`"note":null`)) {
179			t.Fatalf("test setup: archive must carry the null note:\n%s", data)
180		}
181		expectCorruptRuleTextLoad(t, dir, id, "rules[0]", "r-pass", "note")
182	}
183	
184	// --- 每个文本成员写成 null 都判为损坏，错误点名位置、字段与规则 ---
185	
186	func TestLoadReportNullRuleTextFieldRejected(t *testing.T) {
187		// r-bad 是带说明的缺陷规则，七个文本成员全部写出。
188		for _, field := range archiveRuleTextFields {
189			t.Run(field, func(t *testing.T) {
190				dir := t.TempDir()
191				id := writeArchiveWithRuleText(t, dir, oneDefectFixture(), "r-bad", field, `null`)
192				rule := "r-bad"
193				if field == "id" {
194					// id 本身非法时没有可点名的规则标识。
195					rule = ""
196				}
